const b = $input.first().json.body || {};
const s = v => (typeof v === 'string' ? v.trim() : '');
const errors = [];
if (!s(b.client_name)) errors.push('client_name is required');
if (!s(b.message)) errors.push('message is required');
if (b.job_name !== undefined && b.job_name !== null && typeof b.job_name !== 'string') errors.push('job_name must be a string');
if (s(b.client_name).length > 200) errors.push('client_name too long');
if (s(b.message).length > 4000) errors.push('message too long');
return [{ json: { valid: errors.length === 0, errors, client_name: s(b.client_name), message: s(b.message), job_name: s(b.job_name) } }];

const v = $('Validate input').first().json;
const text = x => !x ? '' : (x.title || x.rich_text || []).map(t => t.plain_text).join('');
let job = null;
if (v.job_name) {
  for (const it of $('Notion Pipeline').all()) {
    const p = it.json.properties || {};
    const name = text(p['Job Name']);
    if (name && name.toLowerCase() === v.job_name.toLowerCase()) {
      job = { job_name: name, status: p['Status']?.select?.name || '', job_type: p['Job Type']?.select?.name || '', scheduled_date: p['Scheduled Date']?.date?.start || '', notes: text(p['Notes']), flag_reason: text(p['Flag Reason']) };
      break;
    }
  }
}
return [{ json: { client_name: v.client_name, message: v.message, job_name: v.job_name, job, job_found: !!job } }];

let r;
try {
  let raw = ($json.content?.[0]?.text || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  const o = JSON.parse(m ? m[0] : raw);
  if (typeof o.reply !== 'string' || !o.reply.trim()) throw new Error('no reply');
  r = { reply: o.reply.trim(), needs_human: o.needs_human === true, reason: String(o.reason || '') };
} catch (e) {
  r = { reply: '', needs_human: true, reason: 'Support output could not be parsed; a human should write this reply.' };
}
const c = $('Build context').first().json;
r.client_name = c.client_name;
r.job_name = c.job_name || '';
r.title = 'Reply to ' + c.client_name + (c.job_name ? ' (' + c.job_name + ')' : '');
return [{ json: r }];
